          if (x.V != null) need(isNum(x.V) && x.V > 0 && x.V <= 100, `pufer.${d}.V (mL) mora biti pozitivan broj do 100`);
          validateZapis2(x.zapis_V, x.V, `pufer.${d}.zapis_V`, need);
