    if (s.nacin !== "faraday") for (const f2 of ["operacije", "polureakcije"]) need(!(f2 in s), `${f2} ide samo uz faraday`);
    if (s.nacin === "produkti") {
      for (const f2 of ["struja", "vrijeme", "izluceno", "plin", "trazi", "krivo", "tolerancija_posto"]) need(!(f2 in s), `produkti ne koristi „${f2}“`);
      if (s.pitaj != null && need(Array.isArray(s.pitaj) && s.pitaj.length >= 1, 'pitaj je ["katoda"], ["anoda"] ili oba'))
        s.pitaj.forEach((p) => need(p === "katoda" || p === "anoda", `pitaj: „${p}“ nije katoda ni anoda`));
      return;
    }
    need(s.pitaj == null, "pitaj ide uz produkti");
